import styled, { keyframes, css } from "styled-components";

// Every keyframe and styled-component for the voice assistant panel.
// Extracted from Siri.js so the component file holds behaviour only.

// ============= ENHANCED LIQUID GLASS KEYFRAMES =============
const liquidWave = keyframes`
  0%, 100% { 
    height: 4px;
    opacity: 0.6;
    transform: rotateX(0deg);
  }
  50% { 
    height: 28px;
    opacity: 1;
    transform: rotateX(2deg);
  }
`;

const listeningGlow = keyframes`
  0%, 100% {
    transform: scale(1);
    opacity: 0.6;
  }
  50% {
    transform: scale(1.2);
    opacity: 0.9;
  }
`;
const thinkingGlow = keyframes`
  0%, 100% {
    transform: scale(1);
    opacity: 0.7;
  }
  50% {
    transform: scale(1.3);
    opacity: 1;
  }
`;

const speakingGlow = keyframes`
  0%, 100% {
    transform: scale(1);
    opacity: 0.6;
  }
  25% {
    transform: scale(1.1);
    opacity: 0.9;
  }
  75% {
    transform: scale(1.2);
    opacity: 0.8;
  }
`;

const idleGlow = keyframes`
  0%, 100% {
    transform: scale(1);
    opacity: 0.4;
  }
  50% {
    transform: scale(1.15);
    opacity: 0.7;
  }
`;

// NEW: Enhanced Button Animations
const buttonPulse = keyframes`
  0%, 100% {
    transform: scale(1);
  }
  50% {
    transform: scale(1.05);
  }
`;

const iconRotate = keyframes`
  from {
    transform: rotate(0deg);
  }
  to {
    transform: rotate(360deg);
  }
`;

// ============= ENHANCED LIQUID GLASS STYLED COMPONENTS =============

// The app is wrapped in styled-components' ThemeProvider, so every styled
// component here receives props.theme from context (name: "light" | "dark").
const isLightTheme = (props) => props.theme?.name === "light";

/* ---------------------------------------------------------------
   DARK-MODE SURFACES
   The site's dark theme is a warm charcoal (theme.js body #252827)
   with amber (#FFC107) and red (#F56565) accents. These panels used
   to be an indigo-navy (#3A3C66 → #232542) lit by a purple/cyan
   wash, which read as a different product sitting on top of the
   site. Kept slightly lighter than the page body at the top edge so
   the panel still reads as elevated rather than as a hole.
   Light mode was already correct and is untouched.
   --------------------------------------------------------------- */
const DARK_PANEL =
  "linear-gradient(180deg, rgba(52, 56, 55, 0.88) 0%, rgba(31, 34, 33, 0.94) 100%)";

// Same surface, more opaque — for the notice card, which floats free
// of the panel and needs to stay readable over arbitrary content.
const DARK_PANEL_OPAQUE =
  "linear-gradient(180deg, rgba(52, 56, 55, 0.94) 0%, rgba(31, 34, 33, 0.97) 100%)";

// Ambient wash, in the site's own accents instead of purple/cyan.
const DARK_WASH = `radial-gradient(120% 90% at 15% -10%, rgba(255, 193, 7, 0.13) 0%, transparent 55%),
   radial-gradient(120% 90% at 90% -20%, rgba(245, 101, 101, 0.11) 0%, transparent 55%)`;

const panelEnter = keyframes`
  from {
    opacity: 0;
    transform: translateY(16px) scale(0.97);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
`;

const VoiceContainer = styled.div`
  position: fixed;
  bottom: ${(props) =>
    props.isMobile ? (props.isKeyboardOpen ? "8px" : "12px") : "60px"};
  left: ${(props) => (props.isMobile ? "12px" : "30px")};
  right: ${(props) => (props.isMobile ? "12px" : "auto")};
  width: ${(props) => (props.isMobile ? "auto" : "340px")};
  max-width: ${(props) => (props.isMobile ? "320px" : "360px")};
  margin: ${(props) => (props.isMobile ? "0 auto" : "0")};

  /* === PREMIUM GLASS PANEL (theme-aware) === */
  background: ${(props) =>
    isLightTheme(props)
      ? "linear-gradient(180deg, rgba(255, 255, 255, 0.86) 0%, rgba(248, 248, 252, 0.92) 100%)"
      : DARK_PANEL};

  backdrop-filter: ${(props) =>
    props.flatMode ? "none" : "blur(40px) saturate(1.5)"};
  -webkit-backdrop-filter: ${(props) =>
    props.flatMode ? "none" : "blur(40px) saturate(1.5)"};

  border-radius: 28px;
  padding: ${(props) => (props.isMobile ? "14px 14px 12px" : "26px 24px 22px")};

  /* Hairline rim */
  border: 1px solid
    ${(props) =>
      isLightTheme(props)
        ? "rgba(15, 17, 27, 0.08)"
        : "rgba(255, 255, 255, 0.09)"};

  /* Deep, soft elevation */
  box-shadow: ${(props) =>
    isLightTheme(props)
      ? "0 32px 80px rgba(31, 38, 68, 0.18), 0 8px 24px rgba(31, 38, 68, 0.1), inset 0 1px 0 rgba(255, 255, 255, 0.9)"
      : "0 32px 80px rgba(0, 0, 0, 0.55), 0 8px 24px rgba(0, 0, 0, 0.35), inset 0 1px 0 rgba(255, 255, 255, 0.08)"};

  animation: ${(props) =>
    props.motionReduce || props.isClosing
      ? "none"
      : css`
          ${panelEnter} 0.45s cubic-bezier(0.21, 1.02, 0.47, 1) both
        `};

  transition: var(--transition-3d);
  z-index: 1000;

  /* Mobile Specific Optimizations */
  ${(props) =>
    props.isMobile &&
    css`
      max-height: 48vh;
      overflow: hidden;

      @media (max-height: 600px) {
        bottom: 8px;
        max-height: 42vh;
      }

      @media (orientation: landscape) and (max-height: 500px) {
        bottom: 4px;
        max-height: 40vh;
        padding: 10px 10px;
      }
    `}

  /* Accessibility */
  @media (prefers-contrast: high) {
    background: rgba(0, 0, 0, 0.95);
    border-color: rgba(255, 255, 255, 0.8);
  }

  /* Soft aurora wash across the top of the panel */
  &::before {
    content: "";
    position: absolute;
    inset: 0;
    background: ${(props) =>
      isLightTheme(props)
        ? `radial-gradient(120% 90% at 15% -10%, rgba(124, 58, 237, 0.1) 0%, transparent 55%),
           radial-gradient(120% 90% at 90% -20%, rgba(34, 211, 238, 0.08) 0%, transparent 55%)`
        : DARK_WASH};
    border-radius: inherit;
    pointer-events: none;
  }
`;

const VoiceAvatar = styled.button`
  /* Was a styled.div with an onClick — now a real button, so it is
     focusable, operable with Enter/Space, and announced with a name. The
     resets below keep it looking identical to the old div.

     Styling reads the transient $disabled prop, never the DOM disabled
     attribute: a genuinely disabled button would swallow the click that
     requests microphone permission, which is the entire purpose of the
     locked state. */
  appearance: none;
  padding: 0;
  font: inherit;
  color: inherit;

  width: ${(props) => (props.isMobile ? "52px" : "84px")};
  height: ${(props) => (props.isMobile ? "52px" : "84px")};
  border-radius: var(--radius-full);

  /* Aurora orb — state-tinted */
  background: ${(props) => {
    if (props.$disabled)
      return "radial-gradient(circle at 30% 25%, #64748B 0%, #334155 60%, #1E293B 100%)";
    if (props.state === "listening")
      return "radial-gradient(circle at 30% 25%, #6EE7B7 0%, #10B981 55%, #047857 100%)";
    if (props.state === "speaking")
      return "radial-gradient(circle at 30% 25%, #FDA4AF 0%, #F43F5E 55%, #BE123C 100%)";
    if (props.state === "thinking")
      return "radial-gradient(circle at 30% 25%, #FCD34D 0%, #F59E0B 55%, #B45309 100%)";
    return "radial-gradient(circle at 30% 25%, #A78BFA 0%, #6366F1 55%, #312E81 100%)";
  }};

  display: flex;
  align-items: center;
  justify-content: center;
  font-size: ${(props) => (props.isMobile ? "22px" : "32px")};
  cursor: ${(props) => (props.$disabled ? "not-allowed" : "pointer")};
  margin: 0 auto ${(props) => (props.isMobile ? "8px" : "20px")};

  /* Glass rim + inner sheen */
  border: 1px solid rgba(255, 255, 255, 0.28);

  &:focus-visible {
    outline: 3px solid #ffc107;
    outline-offset: 3px;
  }

  box-shadow: 0 12px 32px
      ${(props) => {
        if (props.$disabled) return "rgba(51, 65, 85, 0.45)";
        if (props.state === "listening") return "rgba(16, 185, 129, 0.45)";
        if (props.state === "speaking") return "rgba(244, 63, 94, 0.45)";
        if (props.state === "thinking") return "rgba(245, 158, 11, 0.45)";
        return "rgba(99, 102, 241, 0.45)";
      }},
    inset 0 2px 6px rgba(255, 255, 255, 0.35),
    inset 0 -4px 10px rgba(0, 0, 0, 0.25);

  transition: var(--transition-3d);
  position: relative;
  overflow: visible;

  /* Enhanced Multi-State Glow Effects - Layer 1 (Inner) */
  &::before {
    content: "";
    position: absolute;
    inset: -20px;
    background: ${(props) => {
      if (props.state === "listening")
        return "radial-gradient(circle, rgba(52, 211, 153, 0.45) 0%, rgba(52, 211, 153, 0.18) 40%, transparent 70%)";
      if (props.state === "thinking")
        return "radial-gradient(circle, rgba(251, 191, 36, 0.45) 0%, rgba(251, 191, 36, 0.18) 40%, transparent 70%)";
      if (props.state === "speaking")
        return "radial-gradient(circle, rgba(251, 113, 133, 0.45) 0%, rgba(251, 113, 133, 0.18) 40%, transparent 70%)";
      if (props.$disabled)
        return "radial-gradient(circle, rgba(100, 116, 139, 0.3) 0%, rgba(100, 116, 139, 0.12) 40%, transparent 70%)";
      return "radial-gradient(circle, rgba(139, 92, 246, 0.4) 0%, rgba(99, 102, 241, 0.16) 40%, transparent 70%)";
    }};
    border-radius: var(--radius-full);
    pointer-events: none;
    z-index: -1;
    transform: scale(
      ${(props) => {
        if (props.state === "listening")
          return 1 + (props.voiceIntensity || 0) * 0.6;
        if (props.state === "thinking") return 1.1;
        if (props.state === "speaking") return 1.2;
        return 1;
      }}
    );
    opacity: ${(props) => {
      if (props.state === "listening")
        return 0.8 + (props.voiceIntensity || 0) * 0.4;
      if (props.state === "thinking") return 0.7;
      if (props.state === "speaking") return 0.6;
      if (props.$disabled) return 0.3;
      return 0.5;
    }};
    transition: all 0.3s ease;
    animation: ${(props) => {
      if (props.motionReduce) return "none";
      if (props.state === "listening")
        return css`
          ${listeningGlow} 2s ease-in-out infinite
        `;
      if (props.state === "thinking")
        return css`
          ${thinkingGlow} 1.5s ease-in-out infinite
        `;
      if (props.state === "speaking")
        return css`
          ${speakingGlow} 0.8s ease-in-out infinite
        `;
      if (!props.$disabled)
        return css`
          ${idleGlow} 4s ease-in-out infinite
        `;
      return "none";
    }};
  }

  /* Enhanced Multi-State Glow Effects - Layer 2 (Middle) */
  &::after {
    content: "";
    position: absolute;
    inset: -38px;
    background: ${(props) => {
      if (props.state === "listening")
        return "radial-gradient(circle, rgba(52, 211, 153, 0.25) 0%, rgba(52, 211, 153, 0.1) 30%, transparent 60%)";
      if (props.state === "thinking")
        return "radial-gradient(circle, rgba(251, 191, 36, 0.25) 0%, rgba(251, 191, 36, 0.1) 30%, transparent 60%)";
      if (props.state === "speaking")
        return "radial-gradient(circle, rgba(251, 113, 133, 0.25) 0%, rgba(251, 113, 133, 0.1) 30%, transparent 60%)";
      if (props.$disabled)
        return "radial-gradient(circle, rgba(100, 116, 139, 0.18) 0%, rgba(100, 116, 139, 0.06) 30%, transparent 60%)";
      return "radial-gradient(circle, rgba(99, 102, 241, 0.22) 0%, rgba(34, 211, 238, 0.08) 30%, transparent 60%)";
    }};
    border-radius: var(--radius-full);
    pointer-events: none;
    z-index: -2;
    transform: scale(
      ${(props) => {
        if (props.state === "listening")
          return 1 + (props.voiceIntensity || 0) * 0.4;
        if (props.state === "thinking") return 1.2;
        if (props.state === "speaking") return 1.3;
        return 1;
      }}
    );
    opacity: ${(props) => {
      if (props.state === "listening")
        return 0.6 + (props.voiceIntensity || 0) * 0.3;
      if (props.state === "thinking") return 0.5;
      if (props.state === "speaking") return 0.4;
      if (props.$disabled) return 0.2;
      return 0.3;
    }};
    transition: all 0.4s ease;
    animation: ${(props) => {
      if (props.motionReduce) return "none";
      if (props.state === "listening")
        return css`
          ${listeningGlow} 3s ease-in-out infinite reverse
        `;
      if (props.state === "thinking")
        return css`
          ${thinkingGlow} 2s ease-in-out infinite reverse
        `;
      if (props.state === "speaking")
        return css`
          ${speakingGlow} 1.2s ease-in-out infinite reverse
        `;
      if (!props.$disabled)
        return css`
          ${idleGlow} 5s ease-in-out infinite reverse
        `;
      return "none";
    }};
  }

  &:hover:not(:disabled) {
    transform: translateY(-2px) scale(1.04);
    box-shadow: 0 18px 44px rgba(99, 102, 241, 0.5),
      inset 0 2px 6px rgba(255, 255, 255, 0.4),
      inset 0 -4px 10px rgba(0, 0, 0, 0.25);
  }

  &:active:not(:disabled) {
    transform: translateY(0) scale(0.98);
  }
`;

const VoiceWaves = styled.div`
  display: flex;
  align-items: center;
  justify-content: center;
  gap: ${(props) => (props.isMobile ? "2px" : "5px")};
  height: ${(props) => {
    const active = props.state === "listening" || props.state === "speaking";
    if (props.isMobile) return active ? "18px" : "0px";
    return "40px";
  }};
  margin: ${(props) => {
    const active = props.state === "listening" || props.state === "speaking";
    if (props.isMobile) return active ? "4px 0" : "0";
    return "20px 0";
  }};
  overflow: hidden;
  opacity: ${(props) =>
    props.state === "listening" || props.state === "speaking" ? 1 : 0};
  transition: var(--transition-smooth);

  /* Enhanced 3D Perspective */
  perspective: var(--perspective-light);
  transform-style: ${(props) => (props.flatMode ? "flat" : "preserve-3d")};

  .wave-bar {
    width: ${(props) => (props.isMobile ? "3px" : "4px")};
    background: ${(props) => {
      if (props.state === "listening")
        return "linear-gradient(to top, #059669, #6EE7B7)";
      if (props.state === "speaking")
        return "linear-gradient(to top, #E11D48, #FDA4AF)";
      return "linear-gradient(to top, #4F46E5, #A5B4FC)";
    }};
    border-radius: 999px;

    box-shadow: 0 0 8px
      ${(props) =>
        props.state === "listening"
          ? "rgba(52, 211, 153, 0.4)"
          : props.state === "speaking"
          ? "rgba(251, 113, 133, 0.4)"
          : "rgba(129, 140, 248, 0.4)"};

    /* Enhanced 3D Animation.
       When the live prop is set, the bars are driven by the analyser through
       inline heights instead. The keyframe animates height too, and CSS
       animations outrank inline styles, so it has to be switched off or the
       real levels would never show. */
    animation: ${(props) =>
      props.motionReduce || props.live
        ? "none"
        : css`
            ${liquidWave} 1.5s ease-in-out infinite
          `};
    transition: ${(props) =>
      props.live ? "height 90ms linear, opacity 90ms linear" : "none"};

    transform-origin: bottom center;
    transform-style: preserve-3d;

    &:nth-child(1) {
      animation-delay: 0s;
    }
    &:nth-child(2) {
      animation-delay: 0.1s;
    }
    &:nth-child(3) {
      animation-delay: 0.2s;
    }
    &:nth-child(4) {
      animation-delay: 0.3s;
    }
    &:nth-child(5) {
      animation-delay: 0.4s;
    }
    &:nth-child(6) {
      animation-delay: 0.3s;
    }
    &:nth-child(7) {
      animation-delay: 0.2s;
    }
    &:nth-child(8) {
      animation-delay: 0.1s;
    }
  }
`;

// PREMIUM GHOST VOICE BUTTON — quiet by default, accent only when active
const VoiceButton = styled.button`
  &:focus-visible {
    outline: 2px solid #ffc107;
    outline-offset: 3px;
  }

  width: ${(props) => (props.isMobile ? "44px" : "48px")};
  height: ${(props) => (props.isMobile ? "44px" : "48px")};
  border-radius: var(--radius-full);
  position: relative;
  overflow: hidden;

  border: 1px solid
    ${(props) => {
      if (props.active) return "rgba(255, 255, 255, 0.25)";
      return isLightTheme(props)
        ? "rgba(15, 17, 27, 0.12)"
        : "rgba(255, 255, 255, 0.12)";
    }};

  background: ${(props) => {
    if (props.disabled)
      return isLightTheme(props)
        ? "rgba(15, 17, 27, 0.04)"
        : "rgba(148, 163, 184, 0.06)";
    if (props.active) {
      switch (props.buttonType) {
        case "mic":
          return "linear-gradient(145deg, #F43F5E, #BE123C)";
        case "auto":
          return "linear-gradient(145deg, #6366F1, #4338CA)";
        case "test":
          return "linear-gradient(145deg, #8B5CF6, #6D28D9)";
        case "type":
          /* Typed input uses the site's amber accent, matching the text
             field and follow-up chips it reveals. */
          return "linear-gradient(145deg, #FFC107, #D99B06)";
        case "3d":
          /* Settings toggle — stays quiet even when on */
          return "rgba(20, 184, 166, 0.18)";
        default:
          return "rgba(255, 255, 255, 0.1)";
      }
    }
    return isLightTheme(props)
      ? "rgba(15, 17, 27, 0.05)"
      : "rgba(255, 255, 255, 0.09)";
  }};

  color: ${(props) => {
    if (props.active) {
      if (props.buttonType === "3d") return "#2DD4BF";
      // Amber is light — needs dark ink to stay readable
      if (props.buttonType === "type") return "#1F2221";
      return "#FFFFFF";
    }
    return isLightTheme(props)
      ? "rgba(30, 33, 48, 0.82)"
      : "rgba(226, 232, 240, 0.92)";
  }};
  cursor: ${(props) => (props.disabled ? "not-allowed" : "pointer")};

  box-shadow: ${(props) => {
    if (!props.active || props.buttonType === "3d")
      return "inset 0 1px 0 rgba(255, 255, 255, 0.08), 0 2px 8px rgba(0, 0, 0, 0.2)";
    const glow =
      props.buttonType === "mic"
        ? "rgba(244, 63, 94, 0.45)"
        : props.buttonType === "auto"
        ? "rgba(99, 102, 241, 0.45)"
        : props.buttonType === "type"
        ? "rgba(255, 193, 7, 0.45)"
        : "rgba(139, 92, 246, 0.45)";
    return `0 8px 24px ${glow}, inset 0 1px 0 rgba(255, 255, 255, 0.25)`;
  }};

  transition: all 0.25s cubic-bezier(0.4, 0, 0.2, 1);

  display: flex;
  align-items: center;
  justify-content: center;

  /* Gentle pulse while a live mode is running (not for settings toggles) */
  ${(props) =>
    props.active &&
    !props.motionReduce &&
    props.buttonType !== "3d" &&
    css`
      animation: ${buttonPulse} 2.4s ease-in-out infinite;
    `}

  .icon-wrapper {
    position: relative;
    display: flex;
    align-items: center;
    justify-content: center;
    width: 100%;
    height: 100%;
    transition: transform 0.25s ease;

    ${(props) =>
      props.active &&
      !props.motionReduce &&
      props.buttonType === "auto" &&
      css`
        animation: ${iconRotate} 4s linear infinite;
      `}
  }

  .icon-svg {
    width: ${(props) => (props.isMobile ? "17px" : "20px")};
    height: ${(props) => (props.isMobile ? "17px" : "20px")};
  }

  &:hover:not(:disabled) {
    transform: translateY(-2px);
    border-color: ${(props) =>
      isLightTheme(props) && !props.active
        ? "rgba(15, 17, 27, 0.25)"
        : "rgba(255, 255, 255, 0.3)"};
    background: ${(props) => {
      if (props.active) return undefined;
      switch (props.buttonType) {
        case "mic":
          return "rgba(244, 63, 94, 0.2)";
        case "auto":
          return "rgba(99, 102, 241, 0.22)";
        case "test":
          return "rgba(139, 92, 246, 0.22)";
        case "type":
          return "rgba(255, 193, 7, 0.22)";
        case "3d":
          return "rgba(20, 184, 166, 0.2)";
        default:
          return "rgba(255, 255, 255, 0.14)";
      }
    }};

    .icon-wrapper {
      transform: scale(1.08);
    }
  }

  &:active:not(:disabled) {
    transform: translateY(0) scale(0.96);
  }

  &:disabled {
    opacity: 0.4;
    filter: grayscale(0.6);
  }
`;

// Premium stroke icon set — thin rounded strokes, consistent optical weight

const dotPulse = keyframes`
  0%, 80%, 100% {
    opacity: 0.25;
    transform: scale(0.85);
  }
  40% {
    opacity: 1;
    transform: scale(1);
  }
`;

const rowIn = keyframes`
  from {
    opacity: 0;
    transform: translateY(8px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
`;

const caretBlink = keyframes`
  0%, 45% {
    opacity: 1;
  }
  50%, 100% {
    opacity: 0;
  }
`;

// Live conversation transcript — what was heard and what the AI replied
const TranscriptPanel = styled.div`
  margin: ${(props) => (props.isMobile ? "8px 0" : "12px 0 2px")};
  padding: ${(props) => (props.isMobile ? "8px 10px" : "12px 14px")};
  border-radius: 16px;

  background: ${(props) =>
    isLightTheme(props)
      ? "rgba(15, 17, 27, 0.04)"
      : "rgba(255, 255, 255, 0.06)"};
  border: 1px solid
    ${(props) =>
      isLightTheme(props)
        ? "rgba(15, 17, 27, 0.07)"
        : "rgba(255, 255, 255, 0.09)"};

  display: flex;
  flex-direction: column;
  gap: 8px;
  max-height: ${(props) => (props.isMobile ? "96px" : "150px")};
  overflow-y: auto;
  scroll-behavior: smooth;
  text-align: left;

  scrollbar-width: thin;
  scrollbar-color: rgba(148, 163, 184, 0.35) transparent;

  &::-webkit-scrollbar {
    width: 4px;
  }
  &::-webkit-scrollbar-thumb {
    background: rgba(148, 163, 184, 0.35);
    border-radius: 999px;
  }

  .transcript-row {
    display: flex;
    gap: 8px;
    align-items: flex-start;
    animation: ${rowIn} 0.35s ease both;
    transition: opacity 0.5s ease;
  }

  /* Older exchanges recede — memory-scroll illusion */
  .transcript-row:not(:nth-last-child(-n + 2)) {
    opacity: 0.45;
  }

  .type-caret {
    display: inline-block;
    width: 2px;
    height: 1em;
    margin-left: 2px;
    vertical-align: text-bottom;
    background: currentColor;
    animation: ${caretBlink} 0.9s step-end infinite;
  }

  .transcript-tag {
    flex-shrink: 0;
    font-size: 8.5px;
    font-weight: 700;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    padding: 2px 8px;
    border-radius: 999px;
    margin-top: 2px;
  }

  .tag-you {
    color: ${(props) => (isLightTheme(props) ? "#0e7490" : "#67e8f9")};
    background: rgba(34, 211, 238, 0.14);
  }

  .tag-ai {
    color: ${(props) => (isLightTheme(props) ? "#6d28d9" : "#c4b5fd")};
    background: rgba(139, 92, 246, 0.16);
  }

  .transcript-text {
    font-size: ${(props) => (props.isMobile ? "11px" : "12px")};
    font-weight: 500;
    line-height: 1.55;
    word-break: break-word;
    color: ${(props) =>
      isLightTheme(props)
        ? "rgba(30, 33, 48, 0.85)"
        : "rgba(235, 238, 248, 0.88)"};
  }

  .interim {
    font-style: italic;
    opacity: 0.7;
  }

  .thinking-dots {
    display: inline-flex;
    align-items: center;
    gap: 4px;
    padding-top: 5px;

    span {
      width: 5px;
      height: 5px;
      border-radius: 50%;
      background: currentColor;
      display: inline-block;
      animation: ${dotPulse} 1.2s ease-in-out infinite;

      &:nth-child(2) {
        animation-delay: 0.2s;
      }
      &:nth-child(3) {
        animation-delay: 0.4s;
      }
    }
  }
`;

const noticeIn = keyframes`
  from {
    opacity: 0;
    transform: translateY(-12px) scale(0.97);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
`;

const noticeAccent = (type) => {
  if (type === "error") return "#FB7185";
  if (type === "warning") return "#FBBF24";
  if (type === "success") return "#34D399";
  return "#818CF8";
};

