import {
  VoiceContainer,
  VoiceAvatar,
  VoiceWaves,
  VoiceButton,
  TranscriptPanel,
  NoticeCard,
  VoiceStatus,
  VoiceControls,
  ButtonRow,
  ButtonLabel,
  ConnectionIndicator,
  CloseButton,
  HelpHint,
  TextInputRow,
  TextInputField,
  TextSendButton,
  FollowUpRow,
  FollowUpChip,
  TranscriptTools,
  TranscriptToolButton,
} from "./Siri.styles";
import {
  ButtonIcon,
  AvatarGlyph,
  MicrophoneIcon,
  ThinkingIcon,
  SpeakingIcon,
  ChatBubbleIcon,
  EmailIcon,
  SparkleIcon,
  IconText,
} from "./SiriIcons";
export { HeroTintSampler, PerformanceManager } from "./siriTheme";

// Global Styles with Enhanced Liquid Glass Design Tokens

const TypewriterText = ({ text, instant, onTick }) => {
  const [count, setCount] = useState(instant ? text.length : 0);

  useEffect(() => {
    if (instant) {
      setCount(text.length);
      return undefined;
    }
    setCount(0);
    if (!text) return undefined;
    // Scale the step so long answers finish in ~3-4s instead of crawling
    const step = Math.max(1, Math.ceil(text.length / 140));
    const interval = setInterval(() => {
      setCount((c) => {
        const next = Math.min(text.length, c + step);
        if (next >= text.length) clearInterval(interval);
        return next;
      });
    }, 26);
    return () => clearInterval(interval);
  }, [text, instant]);

  useEffect(() => {
    if (onTick) onTick();
  }, [count, onTick]);

  return (
    <>
      {text.slice(0, count)}
      {count < text.length && <span className="type-caret" />}
    </>
  );
};

// ============= ENHANCED VOICE ASSISTANT PANEL =============
// Presentation only — every behaviour lives in useVoiceEngine.
const VoiceAssistant = ({ onClose, theme: themeProp }) => {
  // Fall back to the app-level ThemeProvider. Callers have forgotten to pass
  // this prop before, which silently made every `theme?.name` check undefined
  // and pinned dependent UI (the email form) to dark.
  const themeFromContext = useTheme();
  const theme = themeProp || themeFromContext;

  const {
    assistantState,
    clearTranscript,
    closeChat,
    connectionStatus,
    copiedTranscript,
    copyTranscript,
    deviceInfo,
    emailInquiryType,
    emailTranscript,
    flatMode,
    followUps,
    handleEmailFormSubmit,
    hasPermission,
    interimTranscript,
    isAutoMode,
    isClosing,
    isFirstInteraction,
    isKeyboardOpen,
    isMetering,
    isVisible,
    motionReduce,
    notice,
    requestMicrophonePermission,
    scrollTranscriptToEnd,
    setShowEmailForm,
    setShowTextInput,
    setTextInput,
    showEmailForm,
    showHelp,
    showTextInput,
    speakIntroduction,
    startListening,
    stopAll,
    submitText,
    suggestionIndex,
    testTTS,
    textInput,
    textInputRef,
    toggleAutoMode,
    toggleFlatMode,
    transcriptEntries,
    transcriptRef,
    voiceIntensity,
    panelRef,
  } = useVoiceEngine({ onClose });

  // ============= ENHANCED GET VOICE STATUS FUNCTION =============

  const getVoiceStatus = () => {
    // Icon configuration
    const iconSize = deviceInfo.isMobile ? 20 : 24;
    const iconColor = "currentColor";

    // 💡 Enhanced Suggestions Array with Icons
    const suggestions = [
      {
        text: deviceInfo.isMobile
          ? 'Tap & say: "I want to recruit Laxman"'
          : 'Click & say: "I want to recruit Laxman"',
        icon: <ChatBubbleIcon size={iconSize} color={iconColor} animated />,
      },
      {
        text: 'Try saying: "Give me a quick overview"',
        icon: <SparkleIcon size={iconSize} color={iconColor} />,
      },
      {
        text: 'Try saying: "Send an email to Laxman"',
        icon: <EmailIcon size={iconSize} color={iconColor} />,
      },
      {
        text: deviceInfo.isMobile
          ? "Tap to start speaking..."
          : "Click avatar to start speaking...",
        icon: <MicrophoneIcon size={iconSize} color={iconColor} animated />,
      },
    ];

    switch (assistantState) {
      case "listening":
        return {
          title: (
            <IconText
              icon={<MicrophoneIcon size={iconSize} color="#10b981" animated />}
              text="Listening..."
            />
          ),
          subtitle: deviceInfo.isMobile
            ? "Speak clearly!"
            : "Speak clearly, I'm listening carefully!",
        };

      case "thinking":
        return {
          title: (
            <IconText
              icon={<ThinkingIcon size={iconSize} color="#3b82f6" />}
              text="Processing..."
            />
          ),
          subtitle: deviceInfo.isMobile
            ? "AI analyzing..."
            : "AI finding the perfect answer...",
        };

      case "speaking":
        return {
          title: (
            <IconText
              icon={<SpeakingIcon size={iconSize} color="#8b5cf6" />}
              text="Speaking..."
            />
          ),
          subtitle: deviceInfo.isMobile
            ? "Response playing"
            : "Delivering your response",
        };

      default:
        return {
          title: deviceInfo.isMobile
            ? "Laxman's AI Assistant"
            : "Laxman's Enhanced AI",
          subtitle:
            connectionStatus === "connected" ? (
              <IconText
                icon={suggestions[suggestionIndex]?.icon}
                text={suggestions[suggestionIndex]?.text}
              />
            ) : connectionStatus === "connecting" ? (
              <IconText
                icon={<ThinkingIcon size={iconSize - 4} color={iconColor} />}
                text="Setting up voice features..."
              />
            ) : (
              "Tap the 🔒 to unlock your microphone and start speaking."
            ),
        };
    }
  };

  const statusText = getVoiceStatus();
  const isDisabled = connectionStatus !== "connected" || !hasPermission;

  // Single accessible name for the orb, doubling as the polite live-region
  // announcement — sighted users read the state from its colour.
  const avatarLabel = isDisabled
    ? "Enable microphone to start voice chat"
    : assistantState === "listening"
    ? "Listening — activate to stop"
    : assistantState === "thinking"
    ? "Thinking — activate to stop"
    : assistantState === "speaking"
    ? "Speaking — activate to stop"
    : "Start talking to Laxman's AI assistant";

  if (!isVisible) return null;

  return (
    <>
      <GlobalLiquidGlassStyles />

      {/* Enhanced Notice */}
      {notice && (
        <NoticeCard
          type={notice.type}
          show={notice.show}
          isMobile={deviceInfo.isMobile}
          flatMode={flatMode}
          theme={theme}
          role="status"
          aria-live="polite"
        >
          <div className="notice-title">{notice.title}</div>
          <div className="notice-content">{notice.content}</div>
        </NoticeCard>
      )}
      {/* ✅ ADD EMAIL FORM MODAL */}
      <EmailFormModal
        show={showEmailForm}
        onClose={() => setShowEmailForm(false)}
        inquiryType={emailInquiryType}
        onSubmit={handleEmailFormSubmit}
        isMobile={deviceInfo.isMobile}
        // themeMode={theme.name === 'light' ? 'light' : 'dark'}
        themeMode={theme?.name === "light" ? "light" : "dark"}
      />

      {/* Enhanced Voice Assistant Container */}
      <VoiceContainer
        ref={panelRef}
        role="dialog"
        aria-label="Laxman's AI voice assistant"
        state={assistantState}
        isClosing={isClosing}
        isMobile={deviceInfo.isMobile}
        isKeyboardOpen={isKeyboardOpen}
        flatMode={flatMode}
        motionReduce={motionReduce}
      >
        <ConnectionIndicator
          status={connectionStatus}
          isMobile={deviceInfo.isMobile}
          motionReduce={motionReduce}
          flatMode={flatMode}
          aria-hidden="true"
        />

        <CloseButton
          onClick={closeChat}
          isMobile={deviceInfo.isMobile}
          flatMode={flatMode}
          theme={theme}
          type="button"
          aria-label="Close voice assistant"
        >
          <span aria-hidden="true">×</span>
        </CloseButton>

        <VoiceAvatar
          state={assistantState}
          $disabled={isDisabled}
          isMobile={deviceInfo.isMobile}
          motionReduce={motionReduce}
          flatMode={flatMode}
          voiceIntensity={voiceIntensity}
          type="button"
          data-primary-control=""
          aria-label={avatarLabel}
          title={
            isDisabled
              ? deviceInfo.isMobile
                ? "Tap to enable voice chat!"
                : "Click to enable voice chat!"
              : avatarLabel
          }
          onClick={async () => {
            if (isDisabled) {
              if (!hasPermission) {
                await requestMicrophonePermission();
              }
              return;
            }

            if (assistantState === "idle") {
              // Initialize speech synthesis context (required for some browsers)
              if (!window.speechSynthesis.speaking) {
                const testUtterance = new SpeechSynthesisUtterance("");
                testUtterance.volume = 0;
                window.speechSynthesis.speak(testUtterance);
                window.speechSynthesis.cancel();
              }

              // First interaction: speak introduction then listen
              if (isFirstInteraction) {
                speakIntroduction();
              } else {
                // Subsequent interactions: directly start listening
                startListening();
              }
            } else {
              stopAll();
            }
          }}
        >
          <AvatarGlyph
            aria-hidden="true"
            state={assistantState}
            disabled={isDisabled}
            isMobile={deviceInfo.isMobile}
          />
        </VoiceAvatar>

        <VoiceStatus
          isMobile={deviceInfo.isMobile}
          flatMode={flatMode}
          theme={theme}
        >
          {/* Sighted users see the orb change colour; this is the equivalent
              cue for a screen reader. */}
          <div className="visually-hidden" aria-live="polite">
            {avatarLabel}
          </div>
          <div className="status-title" aria-hidden="true">
            {statusText.title}
          </div>
          <div className="status-subtitle" aria-hidden="true">
            {statusText.subtitle}
          </div>
        </VoiceStatus>

        {(assistantState === "listening" || assistantState === "speaking") && (
          <VoiceWaves
            state={assistantState}
            isMobile={deviceInfo.isMobile}
            motionReduce={motionReduce}
            flatMode={flatMode}
            live={isMetering && assistantState === "listening"}
            aria-hidden="true"
          >
            {(() => {
              const barCount = deviceInfo.isMobile ? 5 : 7;
              const live = isMetering && assistantState === "listening";
              const maxRise = deviceInfo.isMobile ? 14 : 24;
              return [...Array(barCount)].map((_, i) => {
                // Arch profile so the row reads as a waveform, not a wall
                const arch = Math.sin(((i + 1) / (barCount + 1)) * Math.PI);
                const weight = 0.45 + 0.55 * arch;
                return (
                  <div
                    key={i}
                    className="wave-bar"
                    style={
                      live
                        ? {
                            height: `${4 + voiceIntensity * maxRise * weight}px`,
                            opacity: 0.55 + voiceIntensity * 0.45,
                          }
                        : undefined
                    }
                  />
                );
              });
            })()}
          </VoiceWaves>
        )}

        {(interimTranscript ||
          transcriptEntries.length > 0 ||
          assistantState === "thinking") && (
          <TranscriptPanel
            ref={transcriptRef}
            isMobile={deviceInfo.isMobile}
            role="log"
            aria-live="polite"
            aria-label="Conversation transcript"
          >
            {transcriptEntries.map((entry, i) => (
              <div className="transcript-row" key={entry.id}>
                <span
                  className={`transcript-tag ${
                    entry.role === "you" ? "tag-you" : "tag-ai"
                  }`}
                >
                  {entry.role === "you" ? "You" : "AI"}
                </span>
                <span className="transcript-text">
                  {entry.role === "ai" &&
                  !entry.restored &&
                  !entry.streamed &&
                  i === transcriptEntries.length - 1 ? (
                    <TypewriterText
                      text={entry.text}
                      instant={motionReduce}
                      onTick={scrollTranscriptToEnd}
                    />
                  ) : (
                    entry.text
                  )}
                </span>
              </div>
            ))}
            {!!interimTranscript && (
              // Excluded from the log: interim results change on nearly every
              // frame and would flood a screen reader. The status line above
              // already announces that we're listening.
              <div className="transcript-row" key="interim" aria-hidden="true">
                <span className="transcript-tag tag-you">You</span>
                <span className="transcript-text interim">
                  {interimTranscript}
                  <span className="type-caret" />
                </span>
              </div>
            )}
            {assistantState === "thinking" && (
              <div className="transcript-row" key="thinking" aria-hidden="true">
                <span className="transcript-tag tag-ai">AI</span>
                <span className="transcript-text thinking-dots">
                  <span />
                  <span />
                  <span />
                </span>
              </div>
            )}
          </TranscriptPanel>
        )}

        {transcriptEntries.length > 0 && (
          <TranscriptTools>
            <TranscriptToolButton
              type="button"
              isMobile={deviceInfo.isMobile}
              theme={theme}
              onClick={copyTranscript}
              aria-label={
                copiedTranscript
                  ? "Transcript copied to clipboard"
                  : "Copy transcript to clipboard"
              }
            >
              {copiedTranscript ? "Copied" : "Copy"}
            </TranscriptToolButton>
            <TranscriptToolButton
              type="button"
              isMobile={deviceInfo.isMobile}
              theme={theme}
              onClick={emailTranscript}
              aria-label="Email this transcript to Laxman"
            >
              Email it
            </TranscriptToolButton>
            <TranscriptToolButton
              type="button"
              isMobile={deviceInfo.isMobile}
              theme={theme}
              onClick={clearTranscript}
              aria-label="Clear the conversation"
            >
              Clear
            </TranscriptToolButton>
          </TranscriptTools>
        )}

        {followUps.length > 0 && assistantState === "idle" && (
          <FollowUpRow isMobile={deviceInfo.isMobile}>
            {followUps.map((f, i) => (
              <FollowUpChip
                key={`${f.action || "f"}-${i}`}
                type="button"
                isMobile={deviceInfo.isMobile}
                theme={theme}
                onClick={() => submitText(f.question)}
              >
                {f.question}
              </FollowUpChip>
            ))}
          </FollowUpRow>
        )}

        {showTextInput && (
          <TextInputRow
            isMobile={deviceInfo.isMobile}
            theme={theme}
            onSubmit={(e) => {
              e.preventDefault();
              submitText(textInput);
            }}
          >
            <TextInputField
              ref={textInputRef}
              isMobile={deviceInfo.isMobile}
              theme={theme}
              value={textInput}
              onChange={(e) => setTextInput(e.target.value)}
              placeholder="Type a question about Laxman…"
              aria-label="Type a question about Laxman"
              autoComplete="off"
              disabled={assistantState === "thinking"}
            />
            <TextSendButton
              type="submit"
              isMobile={deviceInfo.isMobile}
              theme={theme}
              disabled={!textInput.trim() || assistantState === "thinking"}
              aria-label="Send question"
              title="Send"
            >
              <svg
                width="17"
                height="17"
                viewBox="0 0 24 24"
                fill="none"
                aria-hidden="true"
              >
                <path
                  d="M4 12h15M13 6l6 6-6 6"
                  stroke="currentColor"
                  strokeWidth="2"
                  strokeLinecap="round"
                  strokeLinejoin="round"
                />
              </svg>
            </TextSendButton>
          </TextInputRow>
        )}

        <VoiceControls isMobile={deviceInfo.isMobile} flatMode={flatMode}>
          <ButtonRow isMobile={deviceInfo.isMobile} flatMode={flatMode}>
            <div style={{ textAlign: "center" }}>
              <VoiceButton
                onClick={assistantState === "idle" ? startListening : stopAll}
                disabled={isDisabled}
                active={assistantState !== "idle"}
                buttonType="mic"
                isMobile={deviceInfo.isMobile}
                motionReduce={motionReduce}
                flatMode={flatMode}
                type="button"
                aria-label={
                  assistantState === "idle"
                    ? "Ask one question"
                    : "Stop the assistant"
                }
                title={
                  assistantState === "idle"
                    ? "Ask one question"
                    : "Stop current action"
                }
              >
                <div className="icon-wrapper">
                  <ButtonIcon
                    type={assistantState === "idle" ? "mic" : "stop"}
                  />
                </div>
              </VoiceButton>
              <ButtonLabel
                disabled={isDisabled}
                isMobile={deviceInfo.isMobile}
                theme={theme}
              >
                {deviceInfo.isMobile ? "One Time" : "One Time\nQuestion"}
              </ButtonLabel>
            </div>

            <div style={{ textAlign: "center" }}>
              <VoiceButton
                active={isAutoMode}
                onClick={toggleAutoMode}
                disabled={isDisabled}
                buttonType="auto"
                isMobile={deviceInfo.isMobile}
                motionReduce={motionReduce}
                flatMode={flatMode}
                type="button"
                aria-pressed={isAutoMode}
                aria-label="Continuous conversation mode"
                title="Toggle continuous conversation mode"
              >
                <div className="icon-wrapper">
                  <ButtonIcon type="auto" />
                </div>
              </VoiceButton>
              <ButtonLabel disabled={isDisabled} isMobile={deviceInfo.isMobile}>
                {deviceInfo.isMobile ? "Auto Mode" : "Auto\nMode"}
              </ButtonLabel>
            </div>

            <div style={{ textAlign: "center" }}>
              <VoiceButton
                onClick={testTTS}
                disabled={!("speechSynthesis" in window)}
                buttonType="test"
                isMobile={deviceInfo.isMobile}
                motionReduce={motionReduce}
                flatMode={flatMode}
                type="button"
                aria-label="Test voice output"
                title="Test voice output"
              >
                <div className="icon-wrapper">
                  <ButtonIcon type="test" />
                </div>
              </VoiceButton>
              <ButtonLabel
                disabled={!("speechSynthesis" in window)}
                isMobile={deviceInfo.isMobile}
              >
                {deviceInfo.isMobile ? "Test Voice" : "Test\nVoice"}
              </ButtonLabel>
            </div>

            <div style={{ textAlign: "center" }}>
              <VoiceButton
                onClick={() => setShowTextInput((v) => !v)}
                active={showTextInput}
                buttonType="type"
                isMobile={deviceInfo.isMobile}
                motionReduce={motionReduce}
                flatMode={flatMode}
                type="button"
                title="Type your question instead"
                aria-label="Type your question instead"
                aria-pressed={showTextInput}
              >
                <div className="icon-wrapper">
                  <ButtonIcon type="keyboard" />
                </div>
              </VoiceButton>
              <ButtonLabel isMobile={deviceInfo.isMobile} theme={theme}>
                {deviceInfo.isMobile ? "Type" : "Type\nInstead"}
              </ButtonLabel>
            </div>

            {!deviceInfo.isMobile && (
              <div style={{ textAlign: "center" }}>
                <VoiceButton
                  onClick={toggleFlatMode}
                  buttonType="3d"
                  active={!flatMode}
                  isMobile={deviceInfo.isMobile}
                  motionReduce={motionReduce}
                  flatMode={flatMode}
                  type="button"
                  aria-pressed={!flatMode}
                  aria-label="3D visual effects"
                  title="Toggle 3D/Flat mode"
                >
                  <div className="icon-wrapper">
                    <ButtonIcon type={flatMode ? "flat" : "3d"} />
                  </div>
                </VoiceButton>
                <ButtonLabel isMobile={deviceInfo.isMobile}>
                  {flatMode ? "Flat\nMode" : "3D\nMode"}
                </ButtonLabel>
              </div>
            )}
          </ButtonRow>
        </VoiceControls>

        <HelpHint
          show={
            showHelp &&
            assistantState === "idle" &&
            connectionStatus === "connected"
          }
          isMobile={deviceInfo.isMobile}
          flatMode={flatMode}
          theme={theme}
          aria-hidden="true"
        >
          🌟{" "}
          {deviceInfo.isMobile
            ? 'Say "Hello" or ask about Laxman!'
            : "Experience agentic AI - navigate & explore!"}
        </HelpHint>
      </VoiceContainer>
    </>
  );
};

// Main Export with Enhanced Liquid Glass

const LiquidGlassSiri = ({ onClose, theme }) => {
  return <VoiceAssistant onClose={onClose} theme={theme} />;
};

export default LiquidGlassSiri;
